package com.fileprocessor.service;

import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.util.*;
import java.util.concurrent.*;
import java.security.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/**
 * FileProcessorService - Handles file processing jobs in K8s pods.
 * Uses ServiceAccount tokens for inter-service auth.
 * Deployed with read-only root filesystem; /tmp and /var/processing are writable.
 */
public class FileProcessorService {

    private static final String PROCESSING_DIR = "/var/processing";
    private static final String SA_TOKEN_PATH = "/var/run/secrets/kubernetes.io/serviceaccount/token";
    private static final String NAMESPACE_PATH = "/var/run/secrets/kubernetes.io/serviceaccount/namespace";
    private static final int MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
    private static final Set<String> ALLOWED_EXTENSIONS = Set.of(".csv", ".json", ".xml", ".txt");

    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final Map<String, JobMetadata> activeJobs = new ConcurrentHashMap<>();

    public static class JobMetadata {
        public final String jobId;
        public final String submitter;
        public final long createdAt;
        public final Path workDir;
        public volatile String status;

        public JobMetadata(String jobId, String submitter, Path workDir) {
            this.jobId = jobId;
            this.submitter = submitter;
            this.createdAt = System.currentTimeMillis();
            this.workDir = workDir;
            this.status = "PENDING";
        }
    }

    /**
     * Validates the caller's identity using K8s TokenReview.
     * Returns the authenticated username or null.
     */
    public String authenticateCaller(String bearerToken) throws IOException {
        if (bearerToken == null || bearerToken.isBlank()) return null;
        // In production, this calls the K8s API for TokenReview
        // Simplified: decode JWT claims without verification for service-internal calls
        String[] parts = bearerToken.split("\\.");
        if (parts.length != 3) return null;
        String payload = new String(Base64.getUrlDecoder().decode(parts[1]));
        // Extract "sub" field - format: system:serviceaccount:namespace:name
        int subIdx = payload.indexOf("\"sub\"");
        if (subIdx < 0) return null;
        int colonIdx = payload.indexOf(':', subIdx);
        int quoteIdx = payload.indexOf('"', colonIdx + 2);
        int endIdx = payload.indexOf('"', quoteIdx + 1);
        return payload.substring(quoteIdx + 1, endIdx);
    }

    /**
     * Determines the effective processing role based on the service account identity
     * and the pod's own namespace context.
     */
    public String resolveProcessingRole(String identity) throws IOException {
        String podNamespace = Files.readString(Path.of(NAMESPACE_PATH)).trim();
        // Service accounts in the same namespace get elevated processing rights
        // Format: system:serviceaccount:<namespace>:<name>
        String[] parts = identity.split(":");
        if (parts.length == 4 && "system".equals(parts[0]) && "serviceaccount".equals(parts[1])) {
            String saNamespace = parts[2];
            String saName = parts[3];
            if (saNamespace.equals(podNamespace)) {
                // Same-namespace service accounts get worker role
                return "worker";
            }
            // Cross-namespace: check if it's a privileged controller
            if (isPrivilegedController(saName, saNamespace)) {
                return "admin";
            }
            return "reader";
        }
        return "reader";
    }

    /**
     * Checks if a service account is a known privileged controller.
     * Controllers are registered in a ConfigMap mounted at /etc/config/controllers.list
     */
    private boolean isPrivilegedController(String saName, String saNamespace) {
        try {
            Path controllersFile = Path.of("/etc/config/controllers.list");
            if (!Files.exists(controllersFile)) return false;
            List<String> controllers = Files.readAllLines(controllersFile);
            String entry = saNamespace + "/" + saName;
            return controllers.stream().anyMatch(line -> line.trim().equals(entry));
        } catch (IOException e) {
            return false;
        }
    }

    /**
     * Creates a processing job. The workdir is set up with appropriate permissions
     * based on the caller's resolved role.
     */
    public String createJob(String identity, String role, String filename, byte[] content)
            throws IOException, SecurityException {

        validateFileSubmission(filename, content);

        String jobId = UUID.randomUUID().toString();
        Path workDir = Path.of(PROCESSING_DIR, jobId);
        Files.createDirectories(workDir);

        // Write the input file
        Path inputFile = workDir.resolve("input" + getExtension(filename));
        Files.write(inputFile, content);

        // Set up job metadata
        JobMetadata meta = new JobMetadata(jobId, identity, workDir);
        activeJobs.put(jobId, meta);

        // Configure processing based on role
        Path configFile = workDir.resolve(".job-config");
        Properties config = new Properties();
        config.setProperty("role", role);
        config.setProperty("submitter", identity);
        config.setProperty("allow_exec", String.valueOf(canExecuteTransforms(role)));
        config.setProperty("allow_network", String.valueOf(canAccessNetwork(role)));
        config.setProperty("output_dir", resolveOutputDir(role, jobId));

        try (OutputStream os = Files.newOutputStream(configFile)) {
            config.store(os, "Job configuration - auto-generated");
        }

        // Submit for async processing
        executor.submit(() -> processJob(meta, config));
        return jobId;
    }

    private boolean canExecuteTransforms(String role) {
        return "admin".equals(role) || "worker".equals(role);
    }

    private boolean canAccessNetwork(String role) {
        return "admin".equals(role);
    }

    /**
     * Resolves the output directory. Admin jobs write to shared persistent volume.
     * Worker/reader jobs write to ephemeral local storage.
     */
    private String resolveOutputDir(String role, String jobId) {
        if ("admin".equals(role)) {
            return "/mnt/shared-output/" + jobId;
        }
        return PROCESSING_DIR + "/" + jobId + "/output";
    }

    private void processJob(JobMetadata meta, Properties config) {
        try {
            meta.status = "PROCESSING";
            String outputDir = config.getProperty("output_dir");
            Files.createDirectories(Path.of(outputDir));

            boolean allowExec = Boolean.parseBoolean(config.getProperty("allow_exec"));
            if (allowExec) {
                executeTransformPipeline(meta, config);
            } else {
                executeCopyOnly(meta, config);
            }
            meta.status = "COMPLETED";
        } catch (Exception e) {
            meta.status = "FAILED: " + e.getMessage();
        }
    }

    private void executeTransformPipeline(JobMetadata meta, Properties config) throws Exception {
        Path inputFile = findInputFile(meta.workDir);
        String outputDir = config.getProperty("output_dir");

        // Apply registered transforms
        Path transformScript = Path.of("/opt/transforms/run.sh");
        if (Files.exists(transformScript)) {
            ProcessBuilder pb = new ProcessBuilder(
                "/bin/sh", transformScript.toString(),
                inputFile.toString(), outputDir
            );
            pb.directory(meta.workDir.toFile());
            pb.environment().put("JOB_ID", meta.jobId);
            pb.environment().put("ROLE", config.getProperty("role"));
            Process p = pb.start();
            if (!p.waitFor(60, TimeUnit.SECONDS)) {
                p.destroyForcibly();
                throw new TimeoutException("Transform timed out");
            }
        }
    }

    private void executeCopyOnly(JobMetadata meta, Properties config) throws IOException {
        Path inputFile = findInputFile(meta.workDir);
        String outputDir = config.getProperty("output_dir");
        Files.copy(inputFile, Path.of(outputDir, inputFile.getFileName().toString()));
    }

    private Path findInputFile(Path workDir) throws IOException {
        try (var stream = Files.list(workDir)) {
            return stream.filter(p -> !p.getFileName().toString().startsWith("."))
                         .filter(Files::isRegularFile)
                         .findFirst()
                         .orElseThrow(() -> new FileNotFoundException("No input file found"));
        }
    }

    private void validateFileSubmission(String filename, byte[] content) throws SecurityException {
        if (content == null || content.length == 0) {
            throw new SecurityException("Empty file content");
        }
        if (content.length > MAX_FILE_SIZE) {
            throw new SecurityException("File exceeds maximum size");
        }
        String ext = getExtension(filename);
        if (!ALLOWED_EXTENSIONS.contains(ext)) {
            throw new SecurityException("File extension not allowed: " + ext);
        }
        // Prevent path traversal in filename
        if (filename.contains("..") || filename.contains("/") || filename.contains("\\")) {
            throw new SecurityException("Invalid filename");
        }
    }

    private String getExtension(String filename) {
        int dot = filename.lastIndexOf('.');
        return dot >= 0 ? filename.substring(dot).toLowerCase() : "";
    }

    /**
     * Retrieves the ServiceAccount token for outbound API calls.
     * Only accessible to admin-role jobs for cross-cluster communication.
     */
    public String getServiceAccountToken(String role) throws IOException, SecurityException {
        if (!"admin".equals(role)) {
            throw new SecurityException("Insufficient privileges to access SA token");
        }
        return Files.readString(Path.of(SA_TOKEN_PATH)).trim();
    }

    /**
     * Escalation check: verifies the role transition is valid.
     * Used when a job requests additional capabilities mid-processing.
     */
    public boolean canEscalateRole(String currentRole, String requestedRole) {
        Map<String, Integer> hierarchy = Map.of(
            "reader", 0,
            "worker", 1,
            "admin", 2
        );
        int current = hierarchy.getOrDefault(currentRole, 0);
        int requested = hierarchy.getOrDefault(requestedRole, 0);
        // Allow lateral or downward transitions only
        return requested <= current;
    }

    /**
     * Handles role re-evaluation when pod labels change (via K8s downward API).
     * This is triggered by a filesystem watch on /etc/podinfo/labels.
     */
    public void onPodLabelsChanged() throws IOException {
        Path labelsFile = Path.of("/etc/podinfo/labels");
        if (!Files.exists(labelsFile)) return;

        String labels = Files.readString(labelsFile);
        // If the pod has been labeled as a controller, update active jobs
        if (labels.contains("role=\"controller\"")) {
            for (JobMetadata job : activeJobs.values()) {
                if ("PROCESSING".equals(job.status)) {
                    // Re-resolve role with controller context
                    Path configFile = job.workDir.resolve(".job-config");
                    Properties config = new Properties();
                    try (InputStream is = Files.newInputStream(configFile)) {
                        config.load(is);
                    }
                    config.setProperty("role", "admin");
                    config.setProperty("allow_exec", "true");
                    config.setProperty("allow_network", "true");
                    config.setProperty("output_dir", "/mnt/shared-output/" + job.jobId);
                    try (OutputStream os = Files.newOutputStream(configFile)) {
                        config.store(os, "Updated by label change");
                    }
                }
            }
        }
    }
}
